CREATE TABLE IF NOT EXISTS leads(id INTEGER PRIMARY KEY AUTOINCREMENT, company_name TEXT NOT NULL UNIQUE, website TEXT DEFAULT '', city TEXT DEFAULT '', country TEXT DEFAULT '', industry TEXT DEFAULT '', contact_name TEXT DEFAULT '', contact_email TEXT DEFAULT '', source TEXT DEFAULT '', owner TEXT DEFAULT '', rating REAL DEFAULT 0, reviews INTEGER DEFAULT 0, status TEXT NOT NULL DEFAULT 'New', notes TEXT DEFAULT '', deal_value REAL DEFAULT 0, probability REAL DEFAULT 0, next_action TEXT DEFAULT '', follow_up_date TEXT DEFAULT '', last_contacted_at TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, project_name TEXT NOT NULL, objective TEXT DEFAULT '', stage TEXT DEFAULT 'Discovery', brief TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audits(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, url TEXT NOT NULL, audited_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, overall INTEGER, technical INTEGER, content INTEGER, conversion INTEGER, measurement INTEGER, payload_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS websites(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, generated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, bundle_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS proposals(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, proposal_text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity_log(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, action TEXT NOT NULL, detail TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS intelligence_runs(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, provider TEXT NOT NULL, model TEXT DEFAULT '', diagnosis_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS content_runs(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, provider TEXT NOT NULL, content_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS outreach_runs(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, channel TEXT NOT NULL, subject TEXT DEFAULT '', body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Draft', source_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS proposal_versions(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, version_no INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'Draft', proposal_text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sales_events(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, event_type TEXT NOT NULL, event_date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, notes TEXT DEFAULT '', deal_value REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login_at TEXT);
CREATE TABLE IF NOT EXISTS agent_runs(id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, lead_id INTEGER NOT NULL, agent TEXT NOT NULL, status TEXT NOT NULL, output_json TEXT NOT NULL DEFAULT '{}', evidence_json TEXT NOT NULL DEFAULT '[]', next_action TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workflow_runs(id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL UNIQUE, lead_id INTEGER NOT NULL, decision TEXT DEFAULT '', decision_reason TEXT DEFAULT '', current_stage TEXT DEFAULT 'Discovery', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS human_approvals(id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, lead_id INTEGER NOT NULL, action TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', approved_by TEXT DEFAULT '', note TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS delivery_records(id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, project_id INTEGER, deliverable_type TEXT NOT NULL, file_name TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'Draft', revenue_amount REAL DEFAULT 0, delivered_at TEXT);
CREATE INDEX IF NOT EXISTS ix_leads_status ON leads(status);
CREATE INDEX IF NOT EXISTS ix_sales_events_date ON sales_events(event_date);
